-- 每个值只出现一次
SELECT DISTINCT city FROM users;
-- 多列去重：整行组合不重复
SELECT DISTINCT city, age FROM users;

SELECT u.name, o.amount
FROM users u
LEFT JOIN orders o ON o.user_id = u.id;

WITH rich AS (
  SELECT * FROM users WHERE balance > 10000
)
SELECT city, COUNT(*) FROM rich GROUP BY city;

-- 删除重复行保留 id 最小的一条
DELETE FROM users
WHERE id NOT IN (
  SELECT MIN(id) FROM users GROUP BY email
);

SELECT DATE(created_at) AS d, COUNT(*)
FROM orders
GROUP BY DATE(created_at);

CREATE INDEX idx_user_city ON users(city);
-- 复合索引注意最左前缀
CREATE INDEX idx_a_b ON t(a, b);  -- 能加速 WHERE a=? 和 WHERE a=? AND b=?

START TRANSACTION;
UPDATE a SET bal = bal - 100 WHERE id = 1;
UPDATE a SET bal = bal + 100 WHERE id = 2;
COMMIT;  -- 出错则 ROLLBACK

-- 脏读/不可重复读/幻读
-- 隔离级别：READ UNCOMMITTED < READ COMMITTED < REPEATABLE READ < SERIALIZABLE
SET TRANSACTION ISOLATION LEVEL READ COMMITTED;

CREATE VIEW v_rich AS
SELECT * FROM users WHERE balance > 10000;
SELECT * FROM v_rich WHERE city = '上海';

SELECT a.name, (SELECT COUNT(*) FROM orders o
  WHERE o.user_id = a.id) AS cnt
FROM users a;

